import{z as A,x as s,o as r,c as p,q as l,j as B,D as E,d as n,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"营运资本","description":"","frontmatter":{"title":"营运资本","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/working-capital.md","filePath":"econ/working-capital.md","lastUpdated":1791413859000}'),d={name:"econ/working-capital.md"};function C(D,a,c,N,m,h){const t=s("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="营运资本" tabindex="-1">营运资本 <a class="header-anchor" href="#营运资本" aria-label="Permalink to &quot;营运资本&quot;">​</a></h1><div class="epigraph"><p>应收、存货与应付是项目的一部分：增长要垫付现金，衰退才释放；把它们排除在资本支出之外，等于高估自由现金流。</p><footer>—— Brealey, Myers and Allen, Principles of Corporate Finance；对照 FCF 课的净经营资产恒等式</footer></div><p><a href="/econ/lease-vs-buy">上一课</a>把长期资产的租与买写清。本课缺口是短期经营资产：营运资本（NWC）如何进入增量 FCFF、周期与通胀下为何特别容易算错。不重做租赁税盾公式，不把现金持有的治理理论提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/fcf-forecasting">自由现金流预测</a>已经写过 \\(\\Delta\\) NWC 进入分子。资本预算仍常把「厂房投资」当唯一初始流出，好像客户会预付、存货自己出现。缺口是机制：NWC 是内生的生产函数——赊销条款、生产周期、供应商信用决定垫付天数。增长时垫付与收入近似成比例，像永续的再投资；项目结束必须把应收收回、存货出清，否则终值里藏着一笔永远不回来的现金。</p><p>与 Jensen 现金：预防性现金是治理与摩擦对象；经营性 NWC 是生产技术。本课只估值经营垫付，不把超额现金写成项目 NPV。</p><p><span class="marginnote">现金转换周期 ≈ 存货天数 + 应收天数 − 应付天数。天数下降释放现金，等价于正的一次性 FCFF，但可能以价格或短缺风险为代价——代价进经营现金流，不是只改周转、不改 EBIT。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>增量 NWC = 项目引起的应收 + 存货 + 经营现金 − 应付。初始垫付是 \\(t=0\\) 流出；之后随收入增长再垫；期末释放是流入。通胀：名义应收膨胀，垫付更多，下一课会与名义折现一起写。季节性：年内高峰垫付不在年末报表里出现，但折现要按月度现金，不能只用年报余额。</p><p>配额与 IRR：营运资本高峰使早期现金更负，IRR 更差、NPV 仍可能很好——又一条比率陷阱。APV：NWC 风险靠近经营，用 \\(r_U\\) 折，不要用税后 \\(r_D\\)。</p>',10)),(r(),B(i,null,{default:E(()=>[o(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SALES%5B%22%E6%94%B6%E5%85%A5%E5%A2%9E%E9%95%BF%22%5D%20--%3E%20AR%5B%22%E5%BA%94%E6%94%B6%20%2F%20%E5%AD%98%E8%B4%A7%E5%9E%AB%E4%BB%98%22%5D%0A%20%20AR%20--%3E%20NWC%5B%22%CE%94NWC%20%E6%B5%81%E5%87%BA%22%5D%0A%20%20AP%5B%22%E5%BA%94%E4%BB%98%22%5D%20--%3E%20NWC%0A%20%20NWC%20--%3E%20FCFF%5B%22FCFF%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20END%5B%22%E9%A1%B9%E7%9B%AE%E7%BB%93%E6%9D%9F%E9%87%8A%E6%94%BE%22%5D%20--%3E%20BACK%5B%22FCFF%20%E6%B5%81%E5%85%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"信用政策是价格：放宽应收等于降价加承担客户 beta。把增长做成「只加收入不加 NWC」是最常见的过关表。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是时间间隔与一价。货物先走、现金后到，企业提供了贸易信贷；供应商同样。贸易信贷是短期债务替代，但风险是客户违约与经营周期，不是公司债 beta。宏观课序里的信贷摩擦会让贸易信贷在银行紧缩时扩张（替代）或收缩（互补）——企业预测要用情景，不要把历史天数当常数。",-1)),(r(),B(i,null,{default:E(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20PAY%5B%22%E4%BB%98%E7%8E%B0%E9%87%91%E4%B9%B0%E5%8E%9F%E6%96%99%22%5D%20--%3E%20INV%5B%22%E5%AD%98%E8%B4%A7%E5%9C%A8%E6%9E%B6%E4%B8%8A%E7%AD%89%E5%BE%85%20DI%20%E5%A4%A9%22%5D%0A%20%20INV%20--%3E%20SELL%5B%22%E5%8D%96%E5%87%BA%E3%80%81%E5%BC%80%E7%A5%A8%EF%BC%8C%E8%BD%AC%E4%B8%BA%E5%BA%94%E6%94%B6%22%5D%0A%20%20SELL%20--%3E%20AR%5B%22%E5%AE%A2%E6%88%B7%E5%9C%A8%20DR%20%E5%A4%A9%E5%90%8E%E4%BB%98%E6%AC%BE%22%5D%0A%20%20AR%20--%3E%20GET%5B%22%E7%8E%B0%E9%87%91%E6%94%B6%E5%9B%9E%EF%BC%8C%E5%BE%AA%E7%8E%AF%E9%97%AD%E5%90%88%22%5D%0A%20%20SUP%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E7%BB%99%20DP%20%E5%A4%A9%E8%B4%A6%E6%9C%9F%22%5D%20--%3E%20NET%5B%22%E5%87%80%E5%8D%A0%E7%94%A8%E5%A4%A9%E6%95%B0%20%3D%20DI%20%2B%20DR%20%E2%88%92%20DP%22%5D%0A%20%20NET%20--%3E%20SIZE%5B%22%E5%9E%AB%E4%BB%98%E7%8E%B0%E9%87%91%20%E2%89%88%20%E6%97%A5%E5%9D%87%E6%88%90%E6%9C%AC%20%C3%97%20%E5%87%80%E5%8D%A0%E7%94%A8%E5%A4%A9%E6%95%B0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">数字实例：设存货 40 天、应收 30 天、应付 20 天，净占用就是 40+30−20=50 天。若项目日均经营成本 2 万元，垫付的营运资本约 2×50=100 万元；收入涨一倍，这笔垫付也涨一倍——和买厂房一样真实的投资，只是常常被忘在表外。</span></p><p>与实物期权：存货是缓冲期权，减少缺货，持有成本是仓储与折现。最优存货不是零 NWC。资本预算若强迫「精益到零」却不计缺货，会高估 NPV。</p><h3 id="应付不是免费资本" tabindex="-1">应付不是免费资本 <a class="header-anchor" href="#应付不是免费资本" aria-label="Permalink to &quot;应付不是免费资本&quot;">​</a></h3><p>拉长应付像无息贷款，但供应商会加价或减服务。净效应进 EBIT 与 NWC 两边。只改应付天数、不改进货价格，是配额游戏。</p><p><span class="marginnote">直觉类比：应付账款是一张没有写利率的贷款——利息并没有消失，只是改由供应商收走：报价上浮、现金折扣取消、发货顺位后移。判断「拉长应付是否划算」，要比较省下的资金成本与多付的货价，两边都得进模型。</span></p><p><span class="marginnote">经营现金（收银台、最低存款）属 NWC；超额现金与有价证券是融资存量，估值时从 EV 得到股权价值时再减，不进项目 FCFF——除非项目改变最低经营现金。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成营运资本管理手册（EOQ 细节）。对象是增量现金进 NPV。现金持有的权衡（预防、税、代理）在治理单元。下一课通胀：名义 NWC 膨胀是隐藏的真实税。</p><p>后课默认：增长垫付、结束释放；NWC 用经营折现率；应付有代价。不要在终值里假设收入永续增长却把 NWC 固定在第 \\(T\\) 年。</p><p><span class="marginnote">常见误区：初学者容易把营运资本当成「永远拿不回来的钱」。它在项目结束时随应收收回、存货出清而回流；若漏掉这笔期末释放，等于把一笔会回来的现金算成永久投资，NPV 被系统性压低，好项目可能被算成坏项目。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>营运资本是项目投资：增长垫付、结束释放，漏记则高估 FCFF。</li><li>信用与存货政策是价格和期权，不是免费的周转改善。</li><li>应付不是无代价的资本；高峰垫付会再次让 IRR 与 NPV 分家。</li><li>出处：Brealey, Myers and Allen；与 Penman 净经营资产恒等式一致。</li></ul>',12))])}const u=A(d,[["render",C]]);export{f as __pageData,u as default};
